sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float x;
uniform float y;
layout(color) uniform half4 color;
uniform float alpha;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.001) return src;
    float inner = float(blurred.eval(coord - float2(x, y)).a);
    float edge = clamp(float(src.a) - inner, 0.0, 1.0);
    float a = edge * clamp(alpha, 0.0, 1.0) * float(color.a);
    half4 shadow = half4(half3(color.rgb) * half(a), half(a));
    return half4(min(src.rgb + shadow.rgb, half3(src.a)), src.a);
}
